"""Generate a zsh completion script from the argparse definitions.

Arguments opt into dynamic completion by setting a `completer` attribute to a key of COMPLETERS.
argparse has no public API for walking subcommands, so this reads its private action lists.
"""

import argparse

COMPLETERS = {
    "skills": "_skillz_names",
    "managed_skills": "_skillz_names --managed",
    "tracked_skills": "_skillz_names --tracked",
    "namespaces": "_skillz_namespaces",
}

HEADER = """#compdef skillz
# Generated by `skillz completions`. Regenerate after changing skillz's commands.

# _arguments passes its own compadd options (such as -J) to these; only --flags go to skillz.
_skillz_names() {
  local -a names
  names=(${(f)"$(skillz _names ${(M)@:#--*} 2>/dev/null)"})
  _describe 'skill' names ${@:#--*}
}

_skillz_namespaces() {
  local -a namespaces
  namespaces=(${(f)"$(skillz _namespaces 2>/dev/null)"})
  _describe 'namespace' namespaces "$@"
}
"""


def zsh_script(parser: argparse.ArgumentParser) -> str:
    subcommands = _subcommands_action(parser)
    visible = [(choice.dest, choice.help or "") for choice in subcommands._choices_actions]
    command_lines = "\n".join(f"    '{_escape_name(name)}:{_quote(text)}'" for name, text in visible)
    cases = "\n".join(_command_case(name, subcommands.choices[name]) for name, _ in visible)
    return (
        f"{HEADER}\n_skillz() {{\n  local -a commands\n  commands=(\n{command_lines}\n  )\n"
        "  _arguments -C '1: :->command' '*:: :->args'\n"
        "  case $state in\n    command) _describe 'command' commands ;;\n"
        f"    args)\n      case $words[1] in\n{cases}\n      esac ;;\n  esac\n}}\n\n_skillz \"$@\"\n"
    )


def _subcommands_action(parser: argparse.ArgumentParser) -> argparse._SubParsersAction:
    return next(a for a in parser._actions if isinstance(a, argparse._SubParsersAction))


def _command_case(name: str, parser: argparse.ArgumentParser) -> str:
    actions = [action for action in parser._actions if not isinstance(action, argparse._HelpAction)]
    options = [_option_spec(action) for action in actions if action.option_strings]
    positionals = [action for action in actions if not action.option_strings]
    specs = [*options, *(_positional_spec(action, index) for index, action in enumerate(positionals, start=1))]
    if not specs:
        return f"        {name}) ;;"
    joined = " \\\n          ".join(specs)
    return f"        {name}) _arguments \\\n          {joined} ;;"


def _completer(action: argparse.Action) -> str:
    return COMPLETERS.get(getattr(action, "completer", ""), "")


def _positional_spec(action: argparse.Action, index: int) -> str:
    position = "*" if action.nargs in ("*", "+") else str(index)
    return f"'{position}:{action.dest}:{_completer(action)}'"


def _option_spec(action: argparse.Action) -> str:
    flags = action.option_strings
    exclusive = f"({' '.join(flags)})"
    takes_value = action.nargs != 0
    value = f":{action.dest}:{_completer(action)}" if takes_value else ""
    return f"'{exclusive}'{{{','.join(flags)}}}'[{_quote(_escape_brackets(action.help or ''))}]{value}'"


def _quote(text: str) -> str:
    return text.replace("'", "'\\''")


def _escape_brackets(text: str) -> str:
    return text.replace("[", "\\[").replace("]", "\\]")


def _escape_name(name: str) -> str:
    return name.replace(":", "\\:")
